mapper.select:

SELECT * FROM (
    SELECT a.*, ROWNUM AS rnum FROM (
        SELECT * FROM (
            /* 1. 동행 게시글 */
            SELECT 'TRAVEL' AS type, 'TRAVEL' AS postType, SEQTRAVELPOST AS seq, TITLE AS title, TO_CLOB(REGEXP_REPLACE(CONTENT, '<[^>]+>', '')) AS content, THUMBNAILURL AS thumbnailUrl, CREATEDATE AS regDate
            FROM TRAVEL_POST WHERE SEQMEMBER = #{seqMember} AND STATUS = 'NORMAL'
            UNION ALL
            /* 2. 일반 게시글 */
            SELECT 'BOARD' AS type, 'BOARD' AS postType, SEQBOARDPOST AS seq, TITLE AS title, TO_CLOB(REGEXP_REPLACE(CONTENT, '<[^>]+>', '')) AS content, THUMBNAILURL AS thumbnailUrl, CREATEDATE AS regDate
            FROM BOARD_POST WHERE SEQMEMBER = #{seqMember} AND STATUS = 'NORMAL'
            UNION ALL
            /* 3. 일반 댓글 */
            SELECT 'COMMENT' AS type, 'BOARD' AS postType, SEQBOARDPOST AS seq, CAST(NULL AS VARCHAR2(255)) AS title, TO_CLOB(CONTENT) AS content, CAST(NULL AS VARCHAR2(2000)) AS thumbnailUrl, CREATEDATE AS regDate
            FROM BOARD_COMMENT WHERE SEQMEMBER = #{seqMember} AND STATUS = 'NORMAL'
            UNION ALL
            /* 4. 동행 댓글 */
            SELECT 'COMMENT' AS type, 'TRAVEL' AS postType, SEQTRAVELPOST AS seq, CAST(NULL AS VARCHAR2(255)) AS title, TO_CLOB(CONTENT) AS content, CAST(NULL AS VARCHAR2(2000)) AS thumbnailUrl, CREATEDATE AS regDate
            FROM TRAVEL_COMMENT WHERE SEQMEMBER = #{seqMember} AND STATUS = 'NORMAL'
        )



                type = #{tab}



        ORDER BY regDate DESC
    ) a WHERE ROWNUM <= #{endRow}   /* M번째까지 */
) WHERE rnum >= #{startRow}         /* N번째부터 */
